import torch
import torch.nn as nn
from torch.utils.cpp_extension import load_inline

cuda_source = r"""
#include <torch/extension.h>
#include <cuda.h>
#include <cuda_runtime.h>

#define TILE 32

__global__ void triu_matmul_kernel(const float* __restrict__ A,
                                    const float* __restrict__ B,
                                    float* __restrict__ C,
                                    int N) {
    int br = blockIdx.y;
    int bc = blockIdx.x;

    int row = br * TILE + threadIdx.y;
    int col = bc * TILE + threadIdx.x;

    // Blocks entirely below the diagonal contribute zero to the result.
    if (bc < br) {
        if (row < N && col < N) {
            C[row * N + col] = 0.0f;
        }
        return;
    }

    __shared__ float As[TILE][TILE];
    __shared__ float Bs[TILE][TILE];

    float sum = 0.0f;

    // Only iterate over the k-blocks that can contain non-zero contributions
    // since A is upper triangular (k >= row block) and B is upper triangular
    // (k <= col block).
    for (int kb = br; kb <= bc; ++kb) {
        int aCol = kb * TILE + threadIdx.x;
        int bRow = kb * TILE + threadIdx.y;

        As[threadIdx.y][threadIdx.x] = (row < N && aCol < N) ? A[row * N + aCol] : 0.0f;
        Bs[threadIdx.y][threadIdx.x] = (bRow < N && col < N) ? B[bRow * N + col] : 0.0f;

        __syncthreads();

        #pragma unroll
        for (int k = 0; k < TILE; ++k) {
            sum += As[threadIdx.y][k] * Bs[k][threadIdx.x];
        }

        __syncthreads();
    }

    if (row < N && col < N) {
        C[row * N + col] = (row <= col) ? sum : 0.0f;
    }
}

torch::Tensor triu_matmul_cuda(torch::Tensor A, torch::Tensor B) {
    TORCH_CHECK(A.is_cuda(), "A must be a CUDA tensor");
    TORCH_CHECK(B.is_cuda(), "B must be a CUDA tensor");
    TORCH_CHECK(A.dim() == 2 && B.dim() == 2, "A and B must be 2D");
    TORCH_CHECK(A.size(0) == A.size(1), "A must be square");
    TORCH_CHECK(B.size(0) == B.size(1), "B must be square");
    TORCH_CHECK(A.size(0) == B.size(0), "A and B must have same size");

    A = A.contiguous();
    B = B.contiguous();

    int N = A.size(0);
    auto C = torch::empty({N, N}, A.options());

    dim3 block(TILE, TILE);
    dim3 grid((N + TILE - 1) / TILE, (N + TILE - 1) / TILE);

    triu_matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );

    return C;
}
"""

cpp_source = r"""
torch::Tensor triu_matmul_cuda(torch::Tensor A, torch::Tensor B);
"""

triu_matmul = load_inline(
    name="triu_matmul",
    cpp_sources=cpp_source,
    cuda_sources=cuda_source,
    functions=["triu_matmul_cuda"],
    verbose=False,
)


class ModelNew(nn.Module):
    """
    Optimized model that performs matrix multiplication (C = A * B) for
    upper triangular matrices using a custom fused CUDA kernel that
    exploits the triangular sparsity structure and fuses the triu masking
    directly into the matmul computation.
    """
    def __init__(self):
        super(ModelNew, self).__init__()

    def forward(self, A, B):
        return triu_matmul.triu_matmul_cuda(A, B)


N = 4096

def get_inputs():
    A = torch.triu(torch.rand(N, N))
    B = torch.triu(torch.rand(N, N))
    return [A.cuda(), B.cuda()]

def get_init_inputs():
    return []

